        {
          "locator": "§3.3 Targeting and Weapons",
          "excerpt": "SFMC-REQ-016 — Targeting Performance\nThe targeting system shall be extremely accurate."
        },
        {
          "locator": "# 11. Open Items",
          "excerpt": "7. Required targeting accuracy."
        }
      ],
      "nasa_references": [
        {
          "document": "NASA-HDBK-2203-5.09",
          "authority": "HANDBOOK_GUIDANCE",
          "section": "§3.2.1.1.4",
          "swe_id": null,
          "url": "https://swehb.nasa.gov/spaces/SWEHBVD/pages/102695669/5.09+-+SRS+-+Software+Requirements+Specification"
        },
        {
          "document": "NPR-7150.2D",
          "authority": "NPR_REQUIREMENT",
          "section": "4.1.2",
          "swe_id": "SWE-050",
